import hashlib, importlib, importlib.metadata, json, pathlib, sys
from click.testing import CliRunner
required = ('autoloader', 'click', 'psutil', 'rich', 'textual',)
modules = {name: importlib.import_module(name) for name in required}
cli_module = importlib.import_module('autoloader.__main__')
if not hasattr(cli_module, 'main'): raise SystemExit('CLI main entrypoint missing')
help_result = CliRunner().invoke(cli_module.cli, ['--help'], prog_name='autoloader', terminal_width=78)
if help_result.exit_code != 0 or not help_result.output.startswith('Usage: autoloader '): raise SystemExit('Click CLI help validation failed')
console_help_sha256 = hashlib.sha256(help_result.output.encode('utf-8')).hexdigest()
dist = importlib.metadata.distribution('libre-core-autoloader')
if dist.metadata.get('Name', '').casefold().replace('_', '-') != 'libre-core-autoloader': raise SystemExit('wrong distribution name')
entries = [ep.value for ep in dist.entry_points if ep.group == 'console_scripts' and ep.name == 'autoloader']
if entries != ['autoloader.__main__:main']: raise SystemExit('AutoLoader console entrypoint missing or ambiguous')
if not str(pathlib.Path(modules['autoloader'].__file__).resolve()).startswith(str(pathlib.Path(sys.prefix).resolve()) + '/'):
    raise SystemExit('AutoLoader package is not installed in the application venv')
wheelhouse = pathlib.Path('/opt/autoloader/wheelhouse')
wheels = list(wheelhouse.glob('*.whl'))
if len(wheels) != 1: raise SystemExit('installed wheelhouse is missing or ambiguous')
wheel_hash = hashlib.sha256(wheels[0].read_bytes()).hexdigest()
if wheel_hash != sys.argv[1]: raise SystemExit('installed wheel fingerprint mismatch')
print(json.dumps({'distribution_name': dist.metadata['Name'], 'distribution_version': dist.version, 'entrypoint': entries[0], 'runtime_imports': sorted(modules), 'wheel_sha256': wheel_hash, 'python_version': sys.version.split()[0], 'console_help_sha256': console_help_sha256, 'console_help_terminal_width': 78}, sort_keys=True))
